127	    /**
128	     * The due-by of a claim of theirs dated {@code date}, fixed when it is made on {@code made} (the sheet's today
129	     * then): the terms-th business day after the date (skipping weekends and the sheet's holidays as they stand now),
130	     * the terms being those in force on the day it is made (see {@link #termsOn}).
131	     */
132	    public LocalDate dueBy(String sheet, LocalDate date, LocalDate made, Settings settings, Holidays holidays) {
