1	package net.officefloor.hq.app.person;
2	
3	import java.sql.Date;
4	import java.time.LocalDate;
5	import java.util.ArrayList;
6	import java.util.HashMap;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.HashSet;
10	import java.util.Locale;
11	import java.util.Set;
12	import net.officefloor.hq.app.alias.Aliases;
13	import net.officefloor.hq.app.setting.Settings;
14	import net.officefloor.hq.app.sheet.SheetClock;
15	import org.springframework.dao.DuplicateKeyException;
16	import org.springframework.jdbc.core.JdbcTemplate;
17	import org.springframework.jdbc.support.GeneratedKeyHolder;
18	import org.springframework.stereotype.Repository;
19	
20	/** The people kept per sheet, each with their grades by from-date. */
21	@Repository
22	public class People {
23	
24	    private static final String COLUMNS = "SELECT id, name, version, retired_from, terms, contact, origin, tags, flag_reason, flag_until FROM person";
25	
26	    private record Row(long id, String name, long version, String retiredFrom, Integer terms, String contact, String origin, String tags,
27	            String flagReason, String flagUntil) {
28	    }
29	
30	    private final JdbcTemplate jdbc;
31	    private final SheetClock clock;
32	    private final Aliases aliases;
33	    private final Settings settings;
34	
35	    public People(JdbcTemplate jdbc, SheetClock clock, Aliases aliases, Settings settings) {
36	        this.jdbc = jdbc;
37	        this.clock = clock;
38	        this.aliases = aliases;
39	        this.settings = settings;
40	    }
41	
42	    /** Every name and alias, lower-cased, on the other sheets of the sheet's tree (its ancestors and descendants). */
43	    private Set<String> treeNames(String sheet) {
44	        Set<String> names = new HashSet<>();
45	        for (String other : settings.tree(sheet)) {
46	            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet = ?", String.class, other));
47	            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ?", String.class, other));
48	        }
49	        return names;
50	    }
51	
52	    /** Whether the name is already a name or alias on another sheet of the sheet's tree, ignoring case. */
53	    public boolean usedInTree(String sheet, String name) {
54	        return treeNames(sheet).contains(name.toLowerCase(Locale.ROOT));
55	    }
56	
57	    /** Whether an alias of the person is already a name or alias on another sheet of the sheet's tree. */
58	    public boolean aliasClashes(String sheet, long id) {
59	        Set<String> names = treeNames(sheet);
60	        return jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ? AND person_id = ?", String.class,
61	                sheet, id).stream().anyMatch(names::contains);
62	    }
63	
64	    private List<Person> query(String sheet, String where, Object... args) {
65	        List<Row> rows = jdbc.query(COLUMNS + " " + where, (rs, i) -> new Row(rs.getLong("id"), rs.getString("name"),
66	                rs.getLong("version"),
67	                rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
68	                rs.getObject("terms", Integer.class), rs.getString("contact"), rs.getString("origin"), rs.getString("tags"),
69	                rs.getString("flag_reason"),
70	                rs.getDate("flag_until") == null ? null : rs.getDate("flag_until").toLocalDate().toString()), args);
71	        if (rows.isEmpty()) {
72	            return List.of();
73	        }
74	        Map<Long, List<GradeFrom>> grades = new HashMap<>();
75	        jdbc.query("SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person p ON p.id = g.person_id"
76	                + " WHERE p.sheet = ? ORDER BY g.person_id, g.from_key", (rs) -> {
77	                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
78	                            .add(new GradeFrom(rs.getString("grade"),
79	                                    rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString()));
80	                }, sheet);
81	        Map<Long, List<TermsFrom>> dated = new HashMap<>();
82	        jdbc.query("SELECT t.person_id, t.terms, t.from_date FROM person_terms t JOIN person p ON p.id = t.person_id"
83	                + " WHERE p.sheet = ? ORDER BY t.person_id, t.from_date", (rs) -> {
84	                    dated.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
85	                            .add(new TermsFrom(rs.getObject("terms", Integer.class),
86	                                    rs.getDate("from_date").toLocalDate().toString()));
87	                }, sheet);
88	        Map<Long, List<Hold>> holds = new HashMap<>();
89	        jdbc.query("SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person p ON p.id = h.person_id"
90	                + " WHERE p.sheet = ? ORDER BY h.person_id, h.id", (rs) -> {
91	                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
92	                            .add(new Hold(rs.getDate("from_date").toLocalDate().toString(),
93	                                    rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString()));
94	                }, sheet);
95	        Map<Long, List<Retirement>> retirements = new HashMap<>();
96	        jdbc.query("SELECT r.person_id, r.from_date, r.to_date FROM person_retirement r JOIN person p ON p.id = r.person_id"
97	                + " WHERE p.sheet = ? ORDER BY r.person_id, r.id", (rs) -> {
98	                    retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
99	                            .add(new Retirement(rs.getDate("from_date").toLocalDate().toString(),
100	                                    rs.getDate("to_date").toLocalDate().toString()));
101	                }, sheet);
102	        Set<String> tree = treeNames(sheet);
103	        Map<Long, List<String>> aliasKeys = new HashMap<>();
104	        jdbc.query("SELECT person_id, alias_key FROM person_alias WHERE sheet = ?", (rs) -> {
105	            aliasKeys.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(rs.getString("alias_key"));
106	        }, sheet);
107	        LocalDate today = clock.today(sheet);
108	        List<Person> people = new ArrayList<>();
109	        for (Row r : rows) {
110	            List<GradeFrom> mine = List.copyOf(grades.getOrDefault(r.id(), List.of()));
111	            List<TermsFrom> terms = new ArrayList<>();
112	            terms.add(new TermsFrom(r.terms(), null));
113	            terms.addAll(dated.getOrDefault(r.id(), List.of()));
114	            people.add(new Person(r.id(), r.name(), Person.gradeOn(mine, today), r.version(), r.retiredFrom(),
115	                    List.copyOf(holds.getOrDefault(r.id(), List.of())), mine, Person.termsOn(terms, today),
116	                    Person.retiredOn(r.retiredFrom(), today), r.contact(),
117	                    tree.contains(r.name().toLowerCase(Locale.ROOT))
118	                            || aliasKeys.getOrDefault(r.id(), List.of()).stream().anyMatch(tree::contains), r.origin(),
119	                    List.copyOf(retirements.getOrDefault(r.id(), List.of())),
120	                    r.tags().isEmpty() ? List.of() : List.of(r.tags().split(",")), List.copyOf(terms),
121	                    r.flagReason(), r.flagUntil(), Person.flaggedOn(r.flagUntil(), today)));
122	        }
123	        return people;
124	    }
125	
126	    /** Everyone on the sheet, in list order (by position; new people go to the end). */
127	    public List<Person> list(String sheet) {
128	        return query(sheet, "WHERE sheet = ? ORDER BY list_position, id", sheet);
129	    }
130	
131	    /** The position after the sheet's last, where a new person goes. */
132	    public static final String NEXT_POSITION = "(SELECT COALESCE(MAX(n.list_position), 0) + 1 FROM person n WHERE n.sheet = ?)";
133	
134	    /** Swaps the list positions of two people on the sheet. */
135	    public void swapPositions(String sheet, long a, long b) {
136	        Long pa = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, a);
137	        Long pb = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, b);
138	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pb, sheet, a);
139	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pa, sheet, b);
140	    }
141	
142	    public Person find(String sheet, long id) {
143	        List<Person> found = query(sheet, "WHERE sheet = ? AND id = ?", sheet, id);
144	        return found.isEmpty() ? null : found.get(0);
145	    }
146	
147	    /** The person on the sheet with this name or alias, ignoring case; null when there is none. */
148	    public Person findByName(String sheet, String name) {
149	        List<Person> found = query(sheet, "WHERE sheet = ? AND name_key = LOWER(?)", sheet, name);
150	        if (found.isEmpty()) {
151	            found = query(sheet, "WHERE sheet = ? AND id IN (SELECT person_id FROM person_alias WHERE sheet = ?"
152	                    + " AND alias_key = LOWER(?))", sheet, sheet, name);
153	        }
154	        return found.isEmpty() ? null : found.get(0);
155	    }
156	
157	    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
158	    public boolean nameTaken(String sheet, String name, Long except) {
159	        Integer taken = jdbc.queryForObject(
160	                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
161	                Integer.class, sheet, name, except, except);
162	        return taken != null && taken > 0;
163	    }
164	
165	    /** Adds the person with their first grade, which applies from the beginning of time. */
166	    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
167	        return add(sheet, name, grade, null, null);
168	    }
169	
170	    /** Adds the person with their first grade, which applies from the beginning of time, their own terms and contact (null: none). */
171	    public Person add(String sheet, String name, String grade, Integer terms, String contact)
172	            throws DuplicatePersonNameException {
173	        if (nameTaken(sheet, name, null) || aliases.taken(sheet, name) || usedInTree(sheet, name)) {
174	            throw new DuplicatePersonNameException(name);
175	        }
176	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
177	        try {
178	            insert(sheet, name, keys);
179	        } catch (DuplicateKeyException e) {
180	            throw new DuplicatePersonNameException(name);
181	        }
182	        long id = keys.getKey().longValue();
183	        setGrade(id, grade, null);
184	        setTerms(id, terms);
185	        setContact(id, contact);
186	        return find(sheet, id);
187	    }
188	
189	    private void insert(String sheet, String name, GeneratedKeyHolder keys) {
190	        jdbc.update(con -> {
191	            var ps = con.prepareStatement("INSERT INTO person (sheet, name, list_position) VALUES (?, ?, "
192	                    + NEXT_POSITION + ")", new String[] { "id" });
193	            ps.setString(1, sheet);
194	            ps.setString(2, name);
195	            ps.setString(3, sheet);
196	            return ps;
197	        }, keys);
198	    }
199	
200	    /** Records the person's grade from the from-date (null: from the beginning of time), replacing the one there for it. */
201	    public void setGrade(long id, String grade, LocalDate from) {
202	        Date date = from == null ? null : Date.valueOf(from);
203	        if (jdbc.update("UPDATE person_grade SET grade = ? WHERE person_id = ? AND from_date IS NOT DISTINCT FROM ?",
204	                grade, id, date) == 0) {
205	            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, ?)", id, grade, date);
206	        }
207	    }
208	
209	    /** Sets the person's own terms from the beginning of time (null: none). */
210	    public void setTerms(long id, Integer terms) {
211	        jdbc.update("UPDATE person SET terms = ? WHERE id = ?", terms, id);
212	    }
213	
214	    /** Records the person's own terms (null: none) from the from-date, replacing the ones there for it. */
215	    public void setTerms(long id, Integer terms, LocalDate from) {
216	        if (jdbc.update("UPDATE person_terms SET terms = ? WHERE person_id = ? AND from_date = ?", terms, id,
217	                Date.valueOf(from)) == 0) {
218	            jdbc.update("INSERT INTO person_terms (person_id, terms, from_date) VALUES (?, ?, ?)", id, terms,
219	                    Date.valueOf(from));
220	        }
221	    }
222	
223	    /** Sets the person's contact (null: none). */
224	    public void setContact(long id, String contact) {
225	        jdbc.update("UPDATE person SET contact = ? WHERE id = ?", contact, id);
226	    }
227	
228	    /** Sets the person's tags (lower-cased, sorted; empty: none). */
229	    public void setTags(long id, List<String> tags) {
230	        jdbc.update("UPDATE person SET tags = ? WHERE id = ?", String.join(",", tags), id);
231	    }
232	
233	    /** Whether someone on the sheet other than {@code except} has this contact. */
234	    public boolean contactTaken(String sheet, String contact, Long except) {
235	        Integer taken = jdbc.queryForObject(
236	                "SELECT COUNT(*) FROM person WHERE sheet = ? AND contact = ? AND (? IS NULL OR id <> ?)",
237	                Integer.class, sheet, contact, except, except);
238	        return taken != null && taken > 0;
239	    }
240	
241	    /** Retire the person from the date. */
242	    public void retire(String sheet, long id, LocalDate from) {
243	        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet = ? AND id = ?", Date.valueOf(from), sheet, id);
244	    }
245	
246	    /** Unretire the person on the date, keeping the retirement from its from-date to that date as a past one. */
247	    public void unretire(String sheet, long id, LocalDate from, LocalDate on) {
248	        jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
249	                Date.valueOf(from), Date.valueOf(on));
250	        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet = ? AND id = ?", sheet, id);
251	    }
252	
253	    /** Adds a hold to the person. */
254	    public void hold(long id, Hold hold) {
255	        jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
256	                Date.valueOf(hold.from()), hold.to() == null ? null : Date.valueOf(hold.to()));
257	    }
258	
259	    /** Flags the person with the reason until the date, replacing any flag they had. */
260	    public void flag(long id, String reason, LocalDate until) {
261	        jdbc.update("UPDATE person SET flag_reason = ?, flag_until = ? WHERE id = ?", reason, Date.valueOf(until), id);
